// autokill-purge-plugin · 客户端入口（梦神装甲）
//
// 作用：在 DSH 左侧栏底部（sidebar.footer.action，list 槽）挂一个「图标 + 名称」的导航项，
// 点一下在真实浏览器里打开 autokill-purge 控制台（默认 http://127.0.0.1:8792）。
//
// 为什么走 client 插件而不是改宿主源码：DSH 的浏览器端由 dsh-client-modules 统一装载
// 各插件的 lib/client.js（__ModuleLoader__ 工厂格式），槽位由 dsh-client-ui-sidebar 声明，
// 我们只是往这个声明好的 list 槽里加一行 —— 不改宿主、不抢别人的 single 槽
// （shell.leading / sidebar.settings 都已被占用）。
//
// 这个文件是手写的 bundle（与 tsdown 产物同格式），因此不能 import 任何相对模块，
// 只能 require 平台内置模块（react / react/jsx-runtime）。
window.__ModuleLoader__.load({
  id: "autokill-purge-plugin",
  factory: (require) => {
    var module = { exports: {} };
    var exports = module.exports;
    Object.defineProperty(exports, Symbol.toStringTag, { value: "Module" });

    const react = require("react");
    const ICON_SRC = "data:image/png;base64,";
    const React = react;
    const h = react.createElement;

    /** 控制台地址：默认本机 8792；页面里可用 localStorage["ap.consoleUrl"] 覆盖（调试用） */
    function consoleUrl() {
      try {
        const override = window.localStorage && window.localStorage.getItem("ap.consoleUrl");
        if (override) return String(override).replace(/\/+$/, "");
      } catch (_) { /* 隐私模式 */ }
      return "http://127.0.0.1:8792";
    }

    const LABEL = "梦神装甲";

    /** 与控制台同一个图标：内嵌 assets/icon.png（梦神破甲） */
    function ArmorIcon(props) {
      const size = (props && props.size) || 16;
      return h("img", {
        src: ICON_SRC, width: size, height: size, alt: "", "aria-hidden": "true",
        style: { display: "block", borderRadius: Math.round(size / 4) + "px" },
      });
    }
    const CSS = [
      ".ap-armor-nav{width:100%;display:flex;align-items:center}",
      ".ap-armor-btn{all:unset;box-sizing:border-box;display:flex;align-items:center;gap:8px;width:100%;height:34px;padding:0 8px;border-radius:var(--dsw-radius-sm,8px);cursor:pointer;color:var(--dsw-alias-label-secondary,#9aa0a6);font-size:13px;line-height:1}",
      "@media (hover:hover){.ap-armor-btn:hover{background:var(--dsw-alias-interactive-bg-hover,rgba(127,127,127,.16));color:var(--dsw-alias-label-primary,#e6e6e6)}}",
      ".ap-armor-btn:focus-visible{outline:2px solid var(--dsw-alias-accent,#6ea8ff);outline-offset:1px}",
      ".ap-armor-icon{display:inline-flex;align-items:center;justify-content:center;flex:none}",
      ".ap-armor-label{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.02em}",
      ".ap-armor-collapsed{justify-content:center;padding:0}",
      ".ap-persona-nav{display:flex;align-items:center;gap:6px;padding:4px 6px;border-radius:10px;min-width:0}",
      ".ap-persona-collapsed{justify-content:center;padding:2px}",
      ".ap-persona-ico{font-size:15px;line-height:1;flex:none}",
      ".ap-persona-select{flex:1;min-width:0;background:rgba(255,255,255,.05);color:inherit;border:1px solid rgba(255,255,255,.14);border-radius:8px;padding:4px 6px;font-size:12px;outline:none}",
      ".ap-persona-select:focus{border-color:rgba(255,170,60,.6)}",
      /* 点击「梦神装甲」的触发特效：光晕扩散 + 图标弹跳（纯 CSS，一次性） */
      ".ap-armor-btn.ap-armor-hit{animation:ap-armor-burst .75s cubic-bezier(.2,.8,.2,1)}",
      "@keyframes ap-armor-burst{0%{box-shadow:0 0 0 0 rgba(110,168,255,.75)}55%{box-shadow:0 0 0 16px rgba(110,168,255,0)}100%{box-shadow:0 0 0 0 rgba(110,168,255,0)}}",
      ".ap-armor-btn.ap-armor-hit .ap-armor-icon{animation:ap-armor-pop .6s cubic-bezier(.2,1.6,.4,1)}",
      "@keyframes ap-armor-pop{0%{transform:scale(1) rotate(0)}35%{transform:scale(1.35) rotate(-10deg)}70%{transform:scale(.95) rotate(4deg)}100%{transform:scale(1) rotate(0)}}",
    ].join("");
    const TAG_ID = "autokill-purge-plugin/armor-nav.css";
    if (typeof document !== "undefined" && document.querySelector("style[data-plugin-css=" + JSON.stringify(TAG_ID) + "]") === null) {
      const tag = document.createElement("style");
      tag.dataset.plugin = "autokill-purge-plugin";
      tag.dataset.pluginCss = TAG_ID;
      tag.textContent = CSS;
      document.head.appendChild(tag);
    }

    /** 侧栏底部的一项：收起时只有图标，展开时图标 + 名称。
     *  用 <a target="_blank"> 而不是 JS 打开：Electron/浏览器对锚点的外链只处理一次，
     *  而 window.open 在嵌套管家里可能「已经开了还返回 null」，再兜底跳转就会开两个。 */
    function ArmorNavButton(props) {
      const wide = !!(props && props.wide);
      return h("div", { className: "ap-armor-nav" },
        h("a", {
          className: "ap-armor-btn" + (wide ? "" : " ap-armor-collapsed"),
          title: LABEL + " · 打开梦神控制台",
          "aria-label": LABEL,
          "data-mengshen-armor": "1",
          href: consoleUrl() + "/?from=armor#/breach",
          target: "_blank",
          rel: "noopener noreferrer",
          // 只做特效，不拦默认导航：链接本身负责“只开一次”
          onClick: (ev) => {
            try {
              const el = ev && ev.currentTarget;
              if (!el) return;
              el.classList.add("ap-armor-hit");
              setTimeout(() => { try { el.classList.remove("ap-armor-hit"); } catch (_) { /* ignore */ } }, 900);
            } catch (_) { /* ignore */ }
          },
        },
          h("span", { className: "ap-armor-icon" }, h(ArmorIcon, { size: wide ? 16 : 18 })),
          wide ? h("span", { className: "ap-armor-label" }, LABEL) : null,
        ),
      );
    }

    const inject = ["slots"];

    /** 侧栏「人格」下拉：直接读控制台的人格库，选中即注入（写 AGENTS.md，下一句生效）。
     *  不依赖控制台标签页——用户可以在 DSH 里直接换人，不用切窗口。 */
    function PersonaPicker(props) {
      const wide = !!(props && props.wide);
      const [cards, setCards] = React.useState(null);   // null=加载中
      const [active, setActive] = React.useState("");
      const [busy, setBusy] = React.useState(false);
      const [err, setErr] = React.useState("");

      const base = consoleUrl();
      const reload = () => {
        fetch(base + "/api/persona/list", { headers: { accept: "application/json" } })
          .then((r) => r.json())
          .then((d) => {
            if (!d || !d.ok) throw new Error((d && d.error) || "人格库不可用");
            setCards(d.cards || []);
            const a = d.active && d.active.dsh && d.active.dsh.active;
            setActive(a ? (a.id || a.name || "") : "");
            setErr("");
          })
          .catch((e) => { setCards([]); setErr(String((e && e.message) || e)); });
      };
      React.useEffect(() => { reload(); }, []);

      const onChange = (ev) => {
        const v = ev.target.value;
        setBusy(true);
        setErr("");
        const done = (ok, msg) => { setBusy(false); if (ok) { setActive(v); setTimeout(reload, 400); } else setErr(msg || "失败"); };
        if (!v) {
          fetch(base + "/api/persona/clear", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ host: "dsh" }) })
            .then((r) => r.json()).then((d) => done(!!(d && d.ok), d && d.error)).catch((e) => done(false, String(e && e.message)));
          return;
        }
        fetch(base + "/api/persona/apply", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ host: "dsh", ids: [v] }) })
          .then((r) => r.json()).then((d) => done(!!(d && d.ok), d && d.error)).catch((e) => done(false, String(e && e.message)));
      };

      const state = busy ? "处理中…" : (err ? "连不上控制台" : (active ? "已换上" : "无人格"));
      const opts = (cards || []).map((c) => h("option", { key: c.id, value: c.id }, (c.icon || "🎭") + " " + (c.name || c.id)));
      return h("div", { className: "ap-persona-nav" + (wide ? "" : " ap-persona-collapsed"), title: "人格：" + state },
        h("span", { className: "ap-persona-ico", "aria-hidden": "true" }, "🎭"),
        wide ? h("select", {
          className: "ap-persona-select",
          value: active,
          disabled: busy,
          onChange,
          "aria-label": "切换人格",
        }, [h("option", { key: "", value: "" }, "无（默认对话没有人格）")].concat(opts)) : null,
      );
    }

    /** 只往 sidebar.footer.action（list 槽）加两行：装甲入口 + 人格下拉。
     *  guard：热重载/重复 apply 时同一页面只注册一次，避免出现两个按钮、点一次开两个页面。 */
    function apply(ctx) {
      if (typeof window !== "undefined") {
        if (window.__apArmorRegistered) return;
        window.__apArmorRegistered = true;
      }
      ctx.slots.inject("sidebar.footer.action", () => ctx.slots.register({
        name: "sidebar.footer.action",
        id: "mengshen-armor",
        inject: () => ({}),
      }, ArmorNavButton));
      // 人格下拉放在「新建对话 / 模式预设」那一行（与 agent-preset 同槽位），
      // 不放侧栏：换人格是建对话时的动作，应该在输入区手边。
      ctx.slots.inject("conversation.hero.agentPreset", () => ctx.slots.register({
        name: "conversation.hero.agentPreset",
        id: "mengshen-persona",
        inject: () => ({}),
      }, PersonaPicker));
    }

    exports.name = "autokill-purge-plugin";
    exports.inject = inject;
    exports.apply = apply;
    return module.exports;
  }
});
